{
"predictors": [
{
"name": "Employee Satisfaction Index",
"construction": "Survey data from employees about job satisfaction, benefits, work-life balance, etc. Standardized and averaged across firms.",
"rationale": "Higher employee satisfaction may lead to increased productivity and better firm performance.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Customer Loyalty Score",
"construction": "Survey data from customers about brand loyalty. Standardized and averaged across firms.",
"rationale": "Strong customer loyalty may indicate a durable competitive advantage, driving higher firm profitability.",
"higher_returns_for": "High values of the measure"
},
{
"name": "R&D Expenditure Ratio",
"construction": "R&D Expenditure divided by Total Sales, annually.",
"rationale": "High R&D investment may lead to future innovations and revenue growth.",
"higher_returns_for": "High values of the measure"
},
{
"name": "CEO Tenure",
"construction": "Number of years the current CEO has been in position.",
"rationale": "Longer CEO tenures may indicate stability and deep firm knowledge, potentially leading to better decision making.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Capital Expenditure to Operating Cash Flow",
"construction": "Capital Expenditures divided by Operating Cash Flow, annually.",
"rationale": "High reinvestment rates could signal future growth.",
"higher_returns_for": "High values of the measure"
},
{
"name": "International Sales Ratio",
"construction": "International Sales divided by Total Sales, annually.",
"rationale": "Firms with more international exposure may benefit from greater market opportunities and diversification.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Product Diversity Index",
"construction": "The number of distinct product lines or business segments of a firm, normalized by firm size.",
"rationale": "Firms with a wider range of products may be more resilient to sector-specific shocks.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Patent Application Growth",
"construction": "Year-over-year change in the number of patent applications filed.",
"rationale": "Rapid growth in patent applications could indicate a firm's strong innovation pipeline.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Environmental Impact Score",
"construction": "Standardized score based on firm's carbon footprint, waste production, energy usage, etc.",
"rationale": "Firms with lower environmental impact may face fewer regulatory risks and public backlash.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Supplier Concentration Ratio",
"construction": "Herfindahl-Hirschman Index calculated from the firm's supplier base.",
"rationale": "Firms reliant on a smaller number of suppliers may face higher supply-chain risks.",
"higher_returns_for": "Low values of the measure"
}
]
}
